<template>
  <section class="qe-wallet" aria-label="创作能量舱">
    <header class="qe-page-heading"><div><span class="qe-kicker"><i></i> YOUR IDEAS, FULLY CHARGED</span><h1>好想法，<span>随时有能量。</span></h1><p>每一份额度，每一次创作，都清清楚楚。</p></div><button type="button" class="qe-refresh" :disabled="refreshing || signing" @click="refresh"><ClientIcon name="refresh" />{{ refreshing ? '正在更新' : '刷新额度' }}</button></header>
    <div v-if="disabled" class="qe-state"><span class="qe-state-gem"><ClientIcon name="wallet" /></span><h2>能量舱还未开放</h2><p>本站暂未开启钱包与签到。你仍可探索当前开放的创作功能。</p><router-link to="/chat" class="qe-primary">回到灵感工作台<ClientIcon name="arrow" /></router-link></div>
    <template v-else>
      <div v-if="overviewError" class="qe-error" role="alert"><ClientIcon name="info" /><span>{{ overviewError }}{{ balance ? '，下方保留上次读取的额度。' : '，余额尚未确认。' }}</span><button type="button" :disabled="refreshing" @click="refresh">重新读取</button></div>
      <div v-if="loading && !balance" class="qe-loading" role="status"><BrandLoader text="正在为灵感补充能量…" :size="44" /><div class="qe-skeleton"><i v-for="n in 4" :key="n"></i></div></div>
      <template v-if="balance">
        <section class="qe-overview" aria-label="账户额度">
          <div class="qe-pass-scene">
            <div class="qe-pass-shadow" aria-hidden="true"></div><i class="qe-pass-orbit" aria-hidden="true"></i>
            <article class="qe-pass"><div class="qe-pass-head"><span>QGAUSS AI</span><b>{{ balance.isMember ? 'MEMBER' : 'CREATOR' }}</b></div><div class="qe-pass-art" aria-hidden="true"><i></i><i></i><i></i><span>Q</span></div><div class="qe-pass-amount"><small>钱包余额</small><strong><em>¥</em>{{ balance.balanceYuan ?? '—' }}</strong></div><footer><span>{{ membershipLabel(balance) }}</span><ClientIcon name="spark" /></footer></article>
            <span class="qe-pass-sticker"><i></i> A LITTLE ENERGY. A LOT OF POSSIBILITY.</span>
          </div>
          <div class="qe-balance-intro"><span class="qe-kicker">MADE FOR YOUR NEXT IDEA</span><h2>你的下一次灵感，<br>已经准备好出发。</h2><p>钱包余额与四类次数分别记录。使用前，到模型或创作台查看当前费用。</p><div class="qe-overview-actions"><router-link to="/recharge" class="qe-primary">补充创作能量<ClientIcon name="arrowUpRight" /></router-link><router-link to="/recharge" class="qe-text-link">已有卡密？去兑换<ClientIcon name="chevronRight" /></router-link></div><small v-if="updatedAt" class="qe-updated">额度读取于 {{ walletDate(updatedAt) }} · 北京时间</small></div>
        </section>
        <section class="qe-pools" aria-label="四类可用次数">
          <article v-for="pool in WALLET_POOLS" :key="pool.key" class="qe-pool" :class="'qe-pool-' + pool.key">
            <header><span class="qe-pool-icon"><ClientIcon :name="pool.icon" /></span><router-link :to="pool.to" :aria-label="'使用' + pool.label + '次数'"><ClientIcon name="arrowUpRight" /></router-link></header>
            <div class="qe-pool-label">{{ pool.label }}<small>{{ pool.caption }}</small></div><div class="qe-pool-value"><strong>{{ count(balance.counts?.[pool.key]) }}</strong><span>次可用</span></div>
            <dl><div><dt>购买剩余</dt><dd>{{ count(balance.paid?.[pool.key]) }}</dd></div><div><dt>今日会员剩余</dt><dd>{{ count(balance.member?.[pool.key]) }}<small> / {{ count(balance.daily?.[pool.key]) }}</small></dd></div></dl>
            <div v-if="count(balance.daily?.[pool.key])" class="qe-daily-meter" role="meter" :aria-label="pool.label + '今日会员剩余'" :aria-valuemin="0" :aria-valuemax="count(balance.daily[pool.key])" :aria-valuenow="Math.min(count(balance.member?.[pool.key]), count(balance.daily[pool.key]))"><i :style="{ width: dailyPercent(pool.key) + '%' }"></i></div>
            <footer><span v-if="count(balance.reserved?.[pool.key])" class="wl-reserved"><i></i>{{ count(balance.reserved[pool.key]) }} 次预留中</span><span v-else>当前无预留</span><span>累计使用 {{ count(balance.used?.[pool.key]) }} 次</span></footer>
          </article>
        </section>
        <p class="qe-pool-note"><ClientIcon name="info" />可用次数已扣除预留；会员每日额度按北京时间刷新，优先于购买次数使用。各类次数不能互换。</p>
      </template>
      <section v-if="balance" class="qe-signin" :class="{ 'is-signed': signin?.signedToday }" aria-labelledby="qe-signin-title">
        <div class="qe-signin-copy"><span class="qe-signin-icon" aria-hidden="true"><ClientIcon :name="signin?.signedToday ? 'check' : 'sun'" /></span><div><span class="qe-kicker">SMALL HABITS. BRIGHT IDEAS.</span><h2 id="qe-signin-title">{{ signin?.signedToday ? '今天的能量，已收好。' : '每天见一面，灵感多一点。' }}</h2><p v-if="signinError" role="alert">{{ signinError }}<button type="button" @click="loadSignin">重新读取</button></p><p v-else-if="!signin">正在读取签到状态…</p><p v-else-if="!signin.enabled">签到活动暂未开放。</p><p v-else-if="signin.signedToday">今日已签到 · 连续 {{ count(signin.streak) }} 天</p><p v-else>今日奖励 {{ count(signin.reward) }} 次{{ poolLabel(signin.rewardPool) }}额度 · 北京时间</p></div></div>
        <div v-if="days.length" class="qe-calendar" aria-label="最近七天签到"><div v-for="day in days" :key="day.key" :class="{ 'is-done': day.signed, 'is-today': day.today }" :aria-label="day.key + (day.signed ? ' 已签到' : ' 未签到')"><small>{{ day.today ? '今天' : '周' + day.label }}</small><span><ClientIcon v-if="day.signed" name="check" /><b v-else>{{ day.day }}</b></span></div></div>
        <button type="button" class="qe-primary qe-sign-button" :disabled="signing || !signin?.enabled || signin?.signedToday || !!signinError" @click="sign"><ClientIcon :name="signing ? 'refresh' : signin?.signedToday ? 'check' : 'plus'" />{{ signing ? '正在领取…' : signin?.signedToday ? '今日已签到' : '签到领能量' }}</button>
        <p v-if="signMessage" class="qe-sign-message" role="status">{{ signMessage }}</p>
      </section>
      <section v-if="balance" class="qe-history" aria-labelledby="qe-history-title">
        <div class="qe-history-heading"><div><span class="qe-kicker">EVERY LITTLE BIT, ACCOUNTED FOR</span><h2 id="qe-history-title">每次创作，都有迹可循。</h2></div><span v-if="logs.total !== null && !logs.loading && !logs.error" class="qe-result-count">共 {{ logs.total }} 条</span></div>
        <div class="qe-tabs" role="tablist" aria-label="账户记录"><button v-for="item in tabs" :id="'qe-tab-' + item.key" :key="item.key" type="button" role="tab" :aria-selected="tab === item.key" :tabindex="tab === item.key ? 0 : -1" aria-controls="qe-log-panel" @click="setTab(item.key)" @keydown="onTabKey($event, item.key)"><ClientIcon :name="item.icon" />{{ item.label }}</button></div>
        <form v-if="tab === 'consume'" class="qe-log-filters" @submit.prevent="applyFilters"><label><span>额度类型</span><select v-model="draftPool" aria-label="额度类型"><option value="">全部额度</option><option v-for="pool in WALLET_POOLS" :key="pool.key" :value="pool.key">{{ pool.label }}</option><option value="money">钱包余额</option></select></label><label><span>流水动作</span><select v-model="draftDirection" aria-label="流水动作"><option value="">全部动作</option><option v-for="(label, key) in directions" :key="key" :value="key">{{ label }}</option></select></label><label class="qe-record-search"><span>模型或说明</span><span><ClientIcon name="search" /><input v-model="draftKeyword" aria-label="搜索流水" type="search" maxlength="100" placeholder="模型名称、说明或业务编号" /></span></label><button type="submit" class="qe-filter-submit" :disabled="logs.loading">筛选<ClientIcon name="arrow" /></button><button v-if="hasFilters" type="button" class="qe-filter-reset" @click="resetFilters">重置</button></form>
        <div id="qe-log-panel" role="tabpanel" :aria-labelledby="'qe-tab-' + tab" :aria-busy="logs.loading">
          <div v-if="logs.loading" class="qe-record-loading" role="status"><BrandLoader :size="30" text="正在整理你的记录…" /></div>
          <div v-else-if="logs.error" class="qe-state qe-record-state" role="alert"><ClientIcon name="info" /><h3>这页记录暂时没到</h3><p>{{ logs.error }}</p><button type="button" class="qe-primary" @click="loadLogs">重新读取</button></div>
          <div v-else-if="!logs.items.length" class="qe-state qe-record-state"><span class="qe-empty-orb" aria-hidden="true">✳</span><h3>{{ hasFilters && tab === 'consume' ? '换个条件，再找找。' : '这一页，等你写下新故事。' }}</h3><p>{{ hasFilters && tab === 'consume' ? '当前没有匹配的流水，试试其他额度或关键词。' : '记录会在发生用量、发放或兑换后出现。' }}</p><button v-if="hasFilters && tab === 'consume'" type="button" class="qe-text-link" @click="resetFilters">查看全部流水<ClientIcon name="arrow" /></button></div>
          <div v-else class="qe-record-list wl-mobile-ledger" role="list" aria-label="账户明细">
            <article v-for="row in logs.items" :key="row.id" role="listitem"><span class="qe-record-icon" :data-direction="row.direction"><ClientIcon :name="recordIcon(row)" /></span><div class="qe-record-copy"><header><strong>{{ tab === 'consume' ? ledgerActivity(row).label : tab === 'crami' ? '卡密兑换' : rechargeSource(row.rechargeType) }}</strong><span v-if="tab === 'consume'" class="qe-record-pool">{{ poolLabel(row.deductionType) }}</span></header><p>{{ tab === 'consume' ? row.modelName || row.remark || '账户用量记录' : grantSummary(row) }}</p><time>{{ walletDate(row.createdAt) }}</time></div><div class="qe-record-amount"><strong>{{ tab === 'consume' ? ledgerActivity(row).quantity : tab === 'crami' ? '已到账' : row.amountCents ? '¥' + (row.amountCents / 100).toFixed(2) : '额度到账' }}</strong><span v-if="tab === 'consume'" :data-positive="ledgerActivity(row).delta > 0">{{ ledgerActivity(row).change }}<small>可用变动</small></span><span v-else>{{ tab === 'crami' ? maskedCode(row.cramiCode) : row.pkgName || '账户发放' }}</span></div><button type="button" class="qe-record-open" :aria-label="'查看记录详情：' + row.id" @click="openRecord(row, $event)"><ClientIcon name="arrowUpRight" /><span>详情</span></button></article>
          </div>
        </div>
        <footer class="qe-history-footer"><p v-if="tab === 'consume'">预留暂减可用；结算只记实际用量，不再次扣除。未用部分按原额度有效期释放。</p><p v-else>到账记录展示当次发放快照，当前剩余额度以上方为准。</p><nav aria-label="记录分页"><button type="button" aria-label="上一页记录" :disabled="logs.loading || logs.page <= 1" @click="changePage(-1)"><ClientIcon name="chevronLeft" /></button><span>第 {{ logs.page }} 页<span v-if="logs.total !== null"> / {{ Math.max(1, Math.ceil(logs.total / pageSize)) }}</span></span><button type="button" aria-label="下一页记录" :disabled="logs.loading || logs.total === null || logs.page * pageSize >= logs.total" @click="changePage(1)"><ClientIcon name="chevronRight" /></button></nav></footer>
      </section>
    </template>
    <dialog ref="receipt" class="qe-receipt" aria-labelledby="qe-receipt-title" @cancel.prevent="closeRecord" @close="onReceiptClosed" @click="onReceiptBackdrop">
      <template v-if="selectedRecord"><header><span class="qe-kicker">YOUR CREATIVE RECEIPT</span><button type="button" aria-label="关闭记录详情" @click="closeRecord"><ClientIcon name="close" /></button></header><div class="qe-receipt-symbol"><ClientIcon :name="recordIcon(selectedRecord.row, selectedRecord.tab)" /></div><h2 id="qe-receipt-title">{{ selectedRecord.tab === 'consume' ? ledgerActivity(selectedRecord.row).label : selectedRecord.tab === 'crami' ? '卡密兑换' : rechargeSource(selectedRecord.row.rechargeType) }}</h2><p class="qe-receipt-total">{{ selectedRecord.tab === 'consume' ? ledgerActivity(selectedRecord.row).quantity : grantSummary(selectedRecord.row) }}</p><dl><div><dt>发生时间</dt><dd>{{ walletDate(selectedRecord.row.createdAt) }}（北京）</dd></div><template v-if="selectedRecord.tab === 'consume'"><div><dt>额度类型</dt><dd>{{ poolLabel(selectedRecord.row.deductionType) }}</dd></div><div><dt>可用变动</dt><dd>{{ ledgerActivity(selectedRecord.row).change }}</dd></div><div><dt>模型</dt><dd>{{ selectedRecord.row.modelName || selectedRecord.row.model || '—' }}</dd></div><div v-if="selectedRecord.row.refId"><dt>业务编号</dt><dd>{{ selectedRecord.row.refId }}</dd></div><div v-if="selectedRecord.row.sourceLogId"><dt>关联流水</dt><dd>{{ selectedRecord.row.sourceLogId }}</dd></div></template><div v-else-if="selectedRecord.tab === 'crami'"><dt>已兑换卡密</dt><dd>{{ selectedRecord.row.cramiCode || '—' }}</dd></div><div v-if="selectedRecord.row.uid"><dt>流水编号</dt><dd>{{ selectedRecord.row.uid }}</dd></div><div><dt>记录编号</dt><dd>{{ selectedRecord.row.id }}</dd></div><div v-if="selectedRecord.row.remark"><dt>说明</dt><dd>{{ selectedRecord.row.remark }}</dd></div></dl><p class="qe-receipt-note">{{ selectedRecord.tab === 'consume' ? '记录表示当次用量动作，可用余额以账户最新额度为准。' : '这是历史到账快照，当前会员与剩余次数以上方账户信息为准。' }}</p><button type="button" class="qe-primary" @click="closeRecord">收好这张记录<ClientIcon name="check" /></button></template>
    </dialog>
  </section>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { api } from '../../api/client.js';
import { useAuth } from '../../stores/auth.js';
import { useBalance } from '../../stores/balance.js';
import { ledgerActivity } from '../../lib/ledger-activity.js';
import { WALLET_POOLS, walletCount as count, walletDate, membershipLabel, signinDays, grantSummary, rechargeSource } from '../../lib/wallet-presentation.js';
import ClientIcon from '../reference/ClientIcon.vue';
import BrandLoader from './BrandLoader.vue';
import './energy-wallet.css';

const { refresh: refreshSharedBalance } = useBalance();
const auth = useAuth(), balance = ref(null), disabled = ref(false), loading = ref(true), refreshing = ref(false), overviewError = ref(''), updatedAt = ref(null);
const signin = ref(null), signinError = ref(''), signing = ref(false), signMessage = ref(''), tab = ref('consume'), receipt = ref(null), selectedRecord = ref(null);
const pageSize = 10, logs = reactive({ items: [], total: null, page: 1, loading: false, error: '' });
const draftPool = ref(''), draftDirection = ref(''), draftKeyword = ref(''), applied = reactive({ pool: '', direction: '', keyword: '' });
const tabs = [{ key: 'consume', label: '用量流水', icon: 'layout' }, { key: 'recharge', label: '到账记录', icon: 'wallet' }, { key: 'crami', label: '兑换记录', icon: 'file' }];
const directions = { 1: '消费与结算', 2: '退款', 3: '失败免扣', 4: '预留', 5: '释放', 6: '到期失效' };
const controllers = new Map();
let active = true, owner = auth.user?.id, receiptOpener = null;
const current = () => active && !!owner && owner === auth.user?.id;
const days = computed(() => signinDays(signin.value?.today, signin.value?.items));
const hasFilters = computed(() => !!(applied.pool || applied.direction || applied.keyword));
function scope(key) { controllers.get(key)?.abort(); const controller = new AbortController(); controllers.set(key, controller); const user = owner; return { signal: controller.signal, current: () => current() && user === owner && !controller.signal.aborted && controllers.get(key) === controller }; }
function poolLabel(key) { return WALLET_POOLS.find(pool => pool.key === key)?.label || (key === 'money' ? '钱包余额' : key || '账户'); }
function dailyPercent(key) { const daily = count(balance.value?.daily?.[key]); return daily ? Math.min(100, count(balance.value?.member?.[key]) / daily * 100) : 0; }
function maskedCode(code) { const text = String(code || ''); return text ? text.slice(0, 4) + ' ··· ' + text.slice(-4) : '已兑换'; }
function recordIcon(row, kind = tab.value) { return kind === 'crami' ? 'file' : kind === 'recharge' ? 'plus' : [2, 5].includes(Number(row.direction)) ? 'refresh' : Number(row.direction) === 4 ? 'settings' : row.bizType==='voice'?'sound':row.bizType==='video'?'video':'spark'; }
async function loadOverview() { const req = scope('overview'); loading.value = true; overviewError.value = ''; try { const data = await api.get('/balance/query', { signal: req.signal }); if (!req.current()) return; balance.value = data; disabled.value = false; updatedAt.value = new Date().toISOString(); } catch (e) { if (!req.current()) return; if (e.status === 404) { disabled.value = true; balance.value = null; closeRecord(false); } else overviewError.value = e.message || '额度暂未读取成功'; } finally { if (req.current()) loading.value = false; } }
async function loadSignin() { const req = scope('signin'); signinError.value = ''; try { const data = await api.get('/signin/signinLog', { signal: req.signal }); if (req.current()) signin.value = data; } catch (e) { if (!req.current()) return; if (e.status === 404) signin.value = { enabled: false }; else signinError.value = '签到状态暂未更新，请重试。'; } }
async function loadLogs() { const req = scope('logs'), kind = tab.value, page = logs.page; logs.loading = true; logs.error = ''; closeRecord(); const query = new URLSearchParams({ page: String(page), pageSize: String(pageSize) }); if (kind === 'consume') { if (applied.pool) query.set('deductionType', applied.pool); if (applied.direction) query.set('direction', applied.direction); if (applied.keyword) query.set('keyword', applied.keyword); } const endpoint = { consume: '/balance/consumeLog', recharge: '/balance/rechargeLog', crami: '/crami/myLog' }[kind]; try { const data = await api.get(endpoint + '?' + query, { signal: req.signal }); if (!req.current() || kind !== tab.value) return; logs.items = Array.isArray(data.items) ? data.items : []; logs.total = Number.isSafeInteger(data.total) && data.total >= 0 ? data.total : null; } catch (e) { if (req.current()) { logs.items = []; logs.total = null; logs.error = e.message || '记录暂未读取成功'; } } finally { if (req.current()) logs.loading = false; } }
async function refresh() { if (refreshing.value || signing.value || !current()) return; refreshing.value = true; const user = owner; try { await loadOverview(); if (current() && !disabled.value && balance.value) await Promise.all([loadSignin(), loadLogs()]); } finally { if (current() && user === owner) refreshing.value = false; } }
function setTab(name) { if (tab.value === name) return; tab.value = name; logs.page = 1; void loadLogs(); }
function onTabKey(event, key) { const index = tabs.findIndex(item => item.key === key); const next = event.key === 'ArrowRight' ? (index + 1) % tabs.length : event.key === 'ArrowLeft' ? (index + tabs.length - 1) % tabs.length : event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : -1; if (next < 0) return; event.preventDefault(); setTab(tabs[next].key); void nextTick(() => document.getElementById('qe-tab-' + tabs[next].key)?.focus()); }
function applyFilters() { applied.pool = draftPool.value; applied.direction = draftDirection.value; applied.keyword = draftKeyword.value.trim(); logs.page = 1; void loadLogs(); }
function resetFilters() { draftPool.value = ''; draftDirection.value = ''; draftKeyword.value = ''; applyFilters(); }
function changePage(delta) { const next = logs.page + delta; if (logs.loading || next < 1 || (delta > 0 && (logs.total === null || (next - 1) * pageSize >= logs.total))) return; logs.page = next; void loadLogs(); }
async function sign() { if (!current() || signing.value || !signin.value?.enabled || signin.value.signedToday || signinError.value) return; const req = scope('sign'); signing.value = true; signMessage.value = ''; try { const result = await api.post('/signin/sign', {}, { signal: req.signal }); if (!req.current()) return; signin.value = { ...signin.value, signedToday: true }; signMessage.value = '签到成功，已到账 ' + count(result.reward) + ' 次' + poolLabel(result.pool) + '额度。'; await Promise.all([loadOverview(), loadSignin(), refreshSharedBalance(), ...(tab.value === 'recharge' ? [loadLogs()] : [])]); } catch (e) { if (!req.current()) return; if (e.status === 409) { signMessage.value = '今天已领取，正在更新额度。'; await Promise.all([loadOverview(), loadSignin(), refreshSharedBalance()]); } else { signMessage.value = '领取结果尚未确认，请重新读取签到状态。'; signinError.value = '请先重新读取，确认是否已到账。'; } } finally { if (req.current()) signing.value = false; } }
async function openRecord(row, event) { receiptOpener = event?.currentTarget; selectedRecord.value = { row, tab: tab.value }; await nextTick(); if (current() && selectedRecord.value && !receipt.value.open) receipt.value.showModal(); }
function closeRecord(restore = true) { if (receipt.value?.open) receipt.value.close(); selectedRecord.value = null; const target = receiptOpener; receiptOpener = null; if (restore && target?.isConnected) target.focus({ preventScroll: true }); }
function onReceiptClosed() { if (!receipt.value?.open && selectedRecord.value) closeRecord(); }
function onReceiptBackdrop(event) { if (event.target !== receipt.value) return; const rect = receipt.value.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) closeRecord(); }
function clear() { for (const controller of controllers.values()) controller.abort(); controllers.clear(); balance.value = null; signin.value = null; logs.items = []; logs.total = null; logs.page = 1; logs.loading = false; logs.error = ''; signing.value = false; refreshing.value = false; signMessage.value = ''; overviewError.value = ''; signinError.value = ''; updatedAt.value = null; tab.value = 'consume'; draftPool.value = ''; draftDirection.value = ''; draftKeyword.value = ''; Object.assign(applied, { pool: '', direction: '', keyword: '' }); loading.value = true; disabled.value = false; closeRecord(false); }
watch(() => auth.user?.id, id => { if (id === owner) return; clear(); owner = id; if (id) void refresh(); });
onMounted(refresh);
onBeforeUnmount(() => { active = false; clear(); });
</script>
